        final String title;final int inputs;final boolean mask;final Param[] params;
        Type(String title,int inputs,boolean mask,Param...params){this.title=title;this.inputs=inputs;this.mask=mask;this.params=params;}
        public String toString(){return title;}
        Channel channel(){return switch(this){case CLIMATE->Channel.CLIMATE;case WATER_LEVEL->Channel.WATER;case MATERIAL_MAP->Channel.MATERIAL;case BIOME_MAP->Channel.BIOME;default->mask?Channel.MASK:Channel.TERRAIN;};}
        Channel inputChannel(int slot){if((this==TREES||this==ROCKS)&&slot==1)return Channel.MASK;if(this==OUTPUT)return switch(slot){case 1->Channel.WATER;case 2,3->Channel.MASK;case 4->Channel.MATERIAL;case 5->Channel.BIOME;default->Channel.TERRAIN;};if(this==BLEND&&slot==2)return Channel.MASK;if((inputs==2&&slot==1)||this==TEMPERATURE||this==RAINFALL)return Channel.CLIMATE;return Channel.TERRAIN;}
        boolean optional(int slot){return this==OUTPUT&&slot>0||this==BLEND&&slot==2||inputs==2&&slot==1||this==CLIMATE;}
        String port(int slot){if((this==TREES||this==ROCKS)&&slot==1)return "Density mask (optional)";if(this==OUTPUT)return new String[]{"Terrain","Water","Snow","Ice","Material","Biome"}[slot];if(inputChannel(slot)==Channel.CLIMATE)return "Climate";return this==BLEND?(slot==0?"Terrain A":slot==1?"Terrain B":"Mask (optional)"):"Terrain";}
